INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('d71cbf89-8f87-414f-8eeb-675a3959172a', '0b8ddab7-b106-4873-bc4d-3987421d265d', 7, 'O Exame da Noite', NULL, '{"intro": "O fim do dia \u00e9 o tempo da colheita e do perd\u00e3o.", "prayer": "Pe\u00e7a perd\u00e3o pelas falhas e agrade\u00e7a pelas vit\u00f3rias.", "practice": "Reveja o seu dia antes de dormir: onde houve amor? Onde faltou?", "reflection": "Ningu\u00e9m melhora o que n\u00e3o avalia.", "journal_prompt": "Se hoje fosse o seu \u00faltimo dia, voc\u00ea estaria em paz?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;